#!/usr/bin/env bash
# verify-role-files.sh — warn when pattern cache files drift from L0 conventions.
#
# Pattern code examples live in be-patterns.md / fe-patterns.md / mobile-patterns.md.
# The required-pattern tokens are PROJECT-SPECIFIC, so they are not hard-coded here:
# they live in scripts/.role-file-checks.txt, generated by /onboard (or written by
# the SA agent after the first codebase scan populates the pattern files).
#
# .role-file-checks.txt format — one check per line, TAB-separated:
#   <relative-file-path>\t<grep -E pattern>\t<human hint>
# Lines starting with # are ignored.
#
# When the checks file is absent (pre-/onboard, or patterns not yet populated),
# this script prints a note and exits 0 — there is nothing meaningful to check.
#
# Pre-commit calls this in warn-only mode (exit 0). For CI use, pass --strict.

set -uo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$REPO_ROOT"

STRICT=0
[[ "${1:-}" == "--strict" ]] && STRICT=1

CHECKS_FILE="scripts/.role-file-checks.txt"

if [[ ! -f "$CHECKS_FILE" ]]; then
    echo "note: $CHECKS_FILE not found — pattern-drift checks skipped."
    echo "      Generate it after the pattern files are populated (SA fills be/fe/mobile-patterns.md):"
    echo "      one check per line: <file>\\t<grep -E pattern>\\t<hint>"
    exit 0
fi

DRIFT=0

echo "── pattern-cache convention sync (from $CHECKS_FILE) ──"
while IFS=$'\t' read -r file pattern hint; do
    [[ -z "$file" || "$file" == \#* ]] && continue
    if [[ ! -f "$file" ]]; then
        echo "  ⚠ $file missing"
        DRIFT=1
        continue
    fi
    if grep -qE "$pattern" "$file"; then
        echo "  ✓ $(basename "$file"): $hint"
    else
        echo "  ✗ $(basename "$file"): missing pattern — $hint"
        DRIFT=1
    fi
done < "$CHECKS_FILE"

echo ""
if (( DRIFT )); then
    echo "Pattern cache files drifted from L0 conventions. Re-sync the pattern files or update $CHECKS_FILE."
    if (( STRICT )); then
        exit 1
    fi
fi
exit 0
